 CREATE FUNCTION grid_worker_validate_audit() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path = pg_catalog, public AS $body$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'GRID_AUDIT_DELETE_FORBIDDEN'; END IF;
  IF (to_jsonb(NEW)-ARRAY['authorized_at','outcome','completed_at','venue_order_id','venue_trade_id','outcome_code']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['authorized_at','outcome','completed_at','venue_order_id','venue_trade_id','outcome_code']) THEN RAISE EXCEPTION 'GRID_AUDIT_IMMUTABLE'; END IF;
  IF NEW.authorized_at IS DISTINCT FROM OLD.authorized_at AND (OLD.authorized_at IS NOT NULL OR NEW.authorized_at IS NULL OR OLD.outcome<>'unknown') THEN RAISE EXCEPTION 'GRID_AUDIT_AUTHORIZATION_LOCKED'; END IF;
  IF ROW(NEW.outcome,NEW.completed_at,NEW.venue_order_id,NEW.venue_trade_id,NEW.outcome_code) IS DISTINCT FROM ROW(OLD.outcome,OLD.completed_at,OLD.venue_order_id,OLD.venue_trade_id,OLD.outcome_code) AND (OLD.outcome<>'unknown' OR NEW.outcome NOT IN ('confirmed','refused','failed') OR NEW.completed_at IS NULL) THEN RAISE EXCEPTION 'GRID_AUDIT_OUTCOME_LOCKED'; END IF;
  RETURN NEW;
END
$body$;
END IF;
